/**
 * Immutable Daily Range close-chart artifact.
 *
 * This is deliberately an SVG generated by the execution process, not a
 * dashboard screenshot or a fresh public-chart query.  Every candle is capped
 * at the confirmed exchange exit timestamp, so reopening a closed report
 * cannot silently pull in later price action.
 */
import { mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { resolve, sep } from "node:path";

import type { FuturesKline } from "./binance-futures-private.js";

export const DAILY_RANGE_CLOSED_CHART_SNAPSHOT_VERSION = "daily-range-closed-chart-svg-v5" as const;

export type DailyRangeClosedChartSnapshot = {
  version: typeof DAILY_RANGE_CLOSED_CHART_SNAPSHOT_VERSION;
  /** CAPTURED assets are immutable. PENDING means the close was safe but the visual feed failed. */
  status: "CAPTURED" | "PENDING" | "UNAVAILABLE";
  requestedAt: string;
  capturedAt: string | null;
  source: "BINANCE_USDM_COMPLETED_CANDLES";
  entryAt: string | null;
  exitAt: string | null;
  assetFile: string | null;
  mimeType: "image/svg+xml" | null;
  fiveMinuteCandleCount: number;
  fourHourCandleCount: number;
  reason: string | null;
};

type SnapshotDirection = "LONG" | "SHORT";
type SnapshotEntryPolicy = "LEGACY_CONTINUATION" | "CONTINUATION" | "FADE";

export type DailyRangeClosedChartSnapshotTrade = Readonly<{
  tradeId: string;
  symbol: string;
  direction: SnapshotDirection;
  entryPolicy?: SnapshotEntryPolicy;
  breakoutDirection?: "UP" | "DOWN" | null;
  entrySubmittedAt: string;
  entryFilledAt: string | null;
  entryFillPrice: number | null;
  exitTimestamp: string | null;
  exitPrice: number | null;
  rangeHigh: number;
  rangeLow: number;
  stopPrice: number | null;
  takeProfitPrice: number | null;
  rrTarget: number;
  referenceTimezone?: "UTC" | "America/New_York";
  referenceRangeOpenTime?: number | null;
  referenceRangeCloseTime?: number | null;
  confirmationBar1: SnapshotCandle;
  confirmationBar2: SnapshotCandle;
}>;

export type SnapshotCandle = Readonly<{
  openTime: number;
  closeTime: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}>;

export type DailyRangeClosedChartSnapshotClient = Pick<
  { getKlines(symbol: string, interval: "5m" | "4h", opts?: { startTime?: number; endTime?: number }): Promise<FuturesKline[]> },
  "getKlines"
>;

const FIVE_MINUTE_MS = 5 * 60_000;
const FIVE_MINUTE_EMA_CONTEXT_BARS = 50;
// This is presentation padding only. No candle after the confirmed exit is
// fetched or rendered; it keeps the final event marker away from the edge.
const CLOSE_LABEL_RIGHT_PADDING_BARS = 3;

const COLORS = {
  background: "#071016",
  panel: "#0b171e",
  border: "#29414c",
  grid: "#263d48",
  text: "#dbe7ec",
  dim: "#8fa5ae",
  up: "#5ce4a6",
  down: "#ff777d",
  entry: "#f8fafc",
  exit: "#c4b5fd",
  stop: "#ff6b6b",
  takeProfit: "#46d39a",
  rangeHigh: "#6fb3d6",
  rangeLow: "#f0b54b",
  acceptance: "#78c8ff",
  ema20: "#eedd88",
  ema50: "#aa4499",
  resistance: "#ff9f66",
  support: "#77b7ff",
} as const;

type OverlayPoint = { openTime: number; value: number };
type StructuralLine = { kind: "RESISTANCE" | "SUPPORT"; points: OverlayPoint[] };
type PriceLevel = { label: string; price: number; color: string; dash?: string };
type SnapshotMarker = {
  label: string;
  at: number;
  price: number;
  color: string;
  position: "above" | "below" | "middle";
  labelAnchor?: "start" | "end";
  labelPosition?: "above" | "below";
};
type SnapshotEvent = { label: string; at: number; price: number; color: string };
type RiskZone = { from: number; to: number; color: string; label: string };

function finite(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function positive(value: unknown): value is number {
  return finite(value) && value > 0;
}

function toMs(value: string | null | undefined): number | null {
  if (!value) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function asSnapshotCandle(value: FuturesKline | SnapshotCandle): SnapshotCandle | null {
  if (!positive(value.openTime) || !positive(value.closeTime)
    || !positive(value.open) || !positive(value.high) || !positive(value.low) || !positive(value.close)
    || !finite(value.volume) || value.volume < 0) return null;
  return {
    openTime: value.openTime,
    closeTime: value.closeTime,
    open: value.open,
    high: value.high,
    low: value.low,
    close: value.close,
    volume: value.volume,
  };
}

function distinctCandles(rows: readonly (FuturesKline | SnapshotCandle)[], startMs: number, exitMs: number): SnapshotCandle[] {
  const unique = new Map<number, SnapshotCandle>();
  for (const row of rows) {
    const candle = asSnapshotCandle(row);
    // A partial candle that was still forming when the exit happened must never
    // appear in a "last chart at close" artifact.
    if (!candle || candle.openTime < startMs || candle.closeTime >= exitMs) continue;
    unique.set(candle.openTime, candle);
  }
  return [...unique.values()].sort((left, right) => left.openTime - right.openTime);
}

function escapeXml(value: string): string {
  return value.replace(/[<>&"']/g, (character) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", "\"": "&quot;", "'": "&apos;" })[character]!);
}

function formatPrice(value: number): string {
  const digits = value < 0.0001 ? 10 : value < 0.01 ? 8 : value < 1 ? 6 : value < 100 ? 4 : 2;
  return new Intl.NumberFormat("en-US", { maximumFractionDigits: digits }).format(value);
}

function formatOverlayPrice(value: number): string {
  const digits = value < 0.0001 ? 10 : value < 0.01 ? 8 : value < 1 ? 6 : value < 100 ? 4 : 2;
  return new Intl.NumberFormat("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
}

function consolidateCoincidentLevels(levels: readonly PriceLevel[]): PriceLevel[] {
  const groups: PriceLevel[][] = [];
  for (const level of levels) {
    const tolerance = Math.max(1e-10, Math.abs(level.price) * 1e-10);
    const group = groups.find((candidate) => Math.abs(candidate[0]!.price - level.price) <= tolerance);
    if (group) group.push(level);
    else groups.push([level]);
  }
  return groups.map((group) => {
    if (group.length === 1) return group[0]!;
    const labels = group.map((level) => level.label);
    const preferred = group.find((level) => level.label === "Exit") ?? group[0]!;
    const fourHourBoundary = labels.find((value) => value === "4H breakout" || value === "4H breakdown");
    const label = labels.includes("Exit") && labels.includes("Stop")
      ? "Exit = Stop"
      : fourHourBoundary && labels.includes("C2 acceptance")
        ? `${fourHourBoundary} = C2 acceptance`
        : labels.join(" = ");
    return { ...preferred, label };
  });
}

function formatTaipeiShort(ms: number): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false,
    timeZone: "Asia/Taipei",
  }).format(new Date(ms)).replace(",", " ");
}

function formatReferenceClock(ms: number, timeZone: "UTC" | "America/New_York"): string {
  return new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit", minute: "2-digit", hour12: false, timeZone,
  }).format(new Date(ms));
}

function referenceSummary(trade: DailyRangeClosedChartSnapshotTrade): string {
  const timeZone = trade.referenceTimezone ?? "UTC";
  const zoneLabel = timeZone === "America/New_York" ? "New York" : "UTC";
  const window = finite(trade.referenceRangeOpenTime) && finite(trade.referenceRangeCloseTime)
    ? `${formatReferenceClock(trade.referenceRangeOpenTime, timeZone)}–${formatReferenceClock(trade.referenceRangeCloseTime, timeZone)}`
    : "persisted";
  return `4H ref ${window} ${zoneLabel} · H ${formatOverlayPrice(trade.rangeHigh)} / L ${formatOverlayPrice(trade.rangeLow)}`;
}

function calculateEma(candles: readonly SnapshotCandle[], period: number): OverlayPoint[] {
  if (candles.length < period) return [];
  const seed = candles.slice(0, period).reduce((sum, candle) => sum + candle.close, 0) / period;
  const multiplier = 2 / (period + 1);
  let value = seed;
  const points: OverlayPoint[] = [{ openTime: candles[period - 1]!.openTime, value }];
  for (let index = period; index < candles.length; index += 1) {
    value = (candles[index]!.close - value) * multiplier + value;
    points.push({ openTime: candles[index]!.openTime, value });
  }
  return points;
}

function latestStructuralLine(candles: readonly SnapshotCandle[], kind: StructuralLine["kind"]): StructuralLine | null {
  const pivots: OverlayPoint[] = [];
  const radius = 2;
  for (let index = radius; index < candles.length - radius; index += 1) {
    const candidate = candles[index]!;
    const candidateValue = kind === "RESISTANCE" ? candidate.high : candidate.low;
    let valid = true;
    for (let offset = 1; offset <= radius; offset += 1) {
      const before = candles[index - offset]!;
      const after = candles[index + offset]!;
      const beforeValue = kind === "RESISTANCE" ? before.high : before.low;
      const afterValue = kind === "RESISTANCE" ? after.high : after.low;
      if (kind === "RESISTANCE" ? candidateValue <= beforeValue || candidateValue <= afterValue : candidateValue >= beforeValue || candidateValue >= afterValue) {
        valid = false;
        break;
      }
    }
    if (valid) pivots.push({ openTime: candidate.openTime, value: candidateValue });
  }
  if (pivots.length < 2) return null;
  const first = pivots[pivots.length - 2]!;
  const second = pivots[pivots.length - 1]!;
  const elapsed = second.openTime - first.openTime;
  if (!(elapsed > 0)) return null;
  const latest = candles.at(-1)!;
  const slope = (second.value - first.value) / elapsed;
  const points = [first, second];
  if (latest.openTime > second.openTime) points.push({ openTime: latest.openTime, value: second.value + slope * (latest.openTime - second.openTime) });
  return { kind, points };
}

function linePoints(points: readonly OverlayPoint[], x: (value: number) => number, y: (value: number) => number, start: number, end: number): string {
  return points
    .filter((point) => point.openTime >= start && point.openTime <= end && finite(point.value))
    .map((point) => `${x(point.openTime).toFixed(2)},${y(point.value).toFixed(2)}`)
    .join(" ");
}

function candleAtOrNearest(candles: readonly SnapshotCandle[], at: number): SnapshotCandle | null {
  let selected: SnapshotCandle | null = null;
  let distance = Number.POSITIVE_INFINITY;
  for (const candle of candles) {
    const nextDistance = Math.abs(candle.openTime - at);
    if (nextDistance < distance) {
      selected = candle;
      distance = nextDistance;
    }
  }
  return selected;
}

function renderPanel(input: {
  x: number;
  y: number;
  width: number;
  height: number;
  title: string;
  subtitle: string;
  candles: SnapshotCandle[];
  allCandles: SnapshotCandle[];
  intervalMs: number;
  viewportStart: number;
  viewportEnd: number;
  levels: PriceLevel[];
  markers: SnapshotMarker[];
  events?: SnapshotEvent[];
  zones?: RiskZone[];
  showStructure?: boolean;
}): string {
  const { x: outerX, y: outerY, width, height, title, subtitle, candles, allCandles, intervalMs, viewportStart, viewportEnd, levels, markers, events = [], zones = [], showStructure = false } = input;
  const left = outerX + 72;
  const right = outerX + width - 148;
  // C1/C2/entry/exit live in a separate event rail.  Nothing verbose is
  // written over the final candles, where four labels used to collide.
  const top = outerY + 82;
  // Keep chart labels and the legend in their own footer space. Previously
  // both occupied the same band, which made the time axis unreadable.
  const bottom = outerY + height - 102;
  const plotWidth = Math.max(1, right - left);
  const plotHeight = Math.max(1, bottom - top);
  const timeStart = Math.min(viewportStart, viewportEnd - intervalMs);
  const timeEnd = Math.max(viewportEnd, timeStart + intervalMs);
  const visible = candles.filter((candle) => candle.openTime + intervalMs > timeStart && candle.openTime <= timeEnd);
  const ema20 = calculateEma(allCandles, 20);
  const ema50 = calculateEma(allCandles, 50);
  const resistance = showStructure ? latestStructuralLine(allCandles, "RESISTANCE") : null;
  const support = showStructure ? latestStructuralLine(allCandles, "SUPPORT") : null;
  const displayedLevels = consolidateCoincidentLevels(levels);
  const values = [
    ...visible.flatMap((candle) => [candle.high, candle.low]),
    ...displayedLevels.map((level) => level.price),
    ...ema20.filter((point) => point.openTime >= timeStart && point.openTime <= timeEnd).map((point) => point.value),
    ...ema50.filter((point) => point.openTime >= timeStart && point.openTime <= timeEnd).map((point) => point.value),
    ...(resistance?.points ?? []).map((point) => point.value),
    ...(support?.points ?? []).map((point) => point.value),
  ].filter(positive);
  const minimum = values.length ? Math.min(...values) : 0;
  const maximum = values.length ? Math.max(...values) : 1;
  const padding = Math.max((maximum - minimum) * 0.1, maximum * 0.001, 1e-10);
  const low = minimum - padding;
  const high = maximum + padding;
  const x = (at: number): number => left + (at - timeStart) / (timeEnd - timeStart) * plotWidth;
  const y = (price: number): number => top + (high - price) / (high - low) * plotHeight;
  const clipId = `clip-${Math.round(outerX)}-${Math.round(outerY)}`;
  const horizontalGrid = Array.from({ length: 5 }, (_, index) => {
    const ratio = index / 4;
    const price = high - ratio * (high - low);
    const yy = top + ratio * plotHeight;
    return `<line x1="${left}" y1="${yy}" x2="${right}" y2="${yy}" stroke="${COLORS.grid}" stroke-width="1" opacity="0.72"/><text x="${right + 10}" y="${yy + 4}" fill="${COLORS.dim}" font-size="13">${escapeXml(formatPrice(price))}</text>`;
  }).join("");
  const verticalGrid = Array.from({ length: 5 }, (_, index) => {
    const ratio = index / 4;
    const at = timeStart + ratio * (timeEnd - timeStart);
    const xx = left + ratio * plotWidth;
    return `<line x1="${xx}" y1="${top}" x2="${xx}" y2="${bottom}" stroke="${COLORS.grid}" stroke-width="1" opacity="0.5"/><text x="${xx}" y="${bottom + 22}" fill="${COLORS.dim}" font-size="12" text-anchor="middle">${escapeXml(formatTaipeiShort(at))}</text>`;
  }).join("");
  const zoneSvg = zones.map((zone) => {
    const from = Math.min(y(zone.from), y(zone.to));
    const to = Math.max(y(zone.from), y(zone.to));
    return `<rect x="${x(viewportStart)}" y="${from}" width="${Math.max(1, x(viewportEnd) - x(viewportStart))}" height="${Math.max(1, to - from)}" fill="${zone.color}" opacity="0.12"/>`;
  }).join("");
  const levelSvg = displayedLevels.map((level) => {
    const yy = y(level.price);
    return `<line x1="${left}" y1="${yy}" x2="${right}" y2="${yy}" stroke="${level.color}" stroke-width="1.5" stroke-dasharray="${level.dash ?? "7 6"}" opacity="0.95"/>`;
  }).join("");
  const candleWidth = Math.max(2, Math.min(14, plotWidth / Math.max(visible.length, 1) * 0.68));
  const candleSvg = visible.map((candle) => {
    const xx = x(candle.openTime + intervalMs / 2);
    const up = candle.close >= candle.open;
    const color = up ? COLORS.up : COLORS.down;
    const openY = y(candle.open);
    const closeY = y(candle.close);
    const bodyY = Math.min(openY, closeY);
    const bodyHeight = Math.max(1, Math.abs(openY - closeY));
    return `<line x1="${xx}" y1="${y(candle.high)}" x2="${xx}" y2="${y(candle.low)}" stroke="${color}" stroke-width="1.2"/><rect x="${xx - candleWidth / 2}" y="${bodyY}" width="${candleWidth}" height="${bodyHeight}" fill="${color}"/>`;
  }).join("");
  const emaSvg = [
    { points: ema20, color: COLORS.ema20, label: "EMA20" },
    { points: ema50, color: COLORS.ema50, label: "EMA50" },
  ].map((line) => {
    const points = linePoints(line.points, x, y, timeStart, timeEnd);
    return points ? `<polyline points="${points}" fill="none" stroke="${line.color}" stroke-width="2"/>` : "";
  }).join("");
  const structureSvg = [resistance, support].filter((line): line is StructuralLine => line !== null).map((line) => {
    const points = linePoints(line.points, x, y, timeStart, timeEnd);
    const color = line.kind === "RESISTANCE" ? COLORS.resistance : COLORS.support;
    return points ? `<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.2"/>` : "";
  }).join("");
  const markerSvg = markers.map((marker) => {
    if (marker.at < timeStart || marker.at > timeEnd || !positive(marker.price)) return "";
    const xx = x(marker.at);
    const yy = y(marker.price);
    const up = marker.position === "above";
    const down = marker.position === "below";
    const labelPosition = marker.labelPosition ?? (down ? "below" : "above");
    const labelY = labelPosition === "above" ? Math.max(top + 14, yy - 16) : Math.min(bottom - 6, yy + 24);
    const triangle = up
      ? `${xx},${yy - 6} ${xx - 5},${yy + 4} ${xx + 5},${yy + 4}`
      : down
        ? `${xx},${yy + 6} ${xx - 5},${yy - 4} ${xx + 5},${yy - 4}`
        : "";
    const shape = marker.position === "middle"
      ? `<circle cx="${xx}" cy="${yy}" r="5" fill="${marker.color}" stroke="#071016" stroke-width="2"/>`
      : `<polygon points="${triangle}" fill="${marker.color}" stroke="#071016" stroke-width="1"/>`;
    const labelAnchor = marker.labelAnchor ?? "start";
    const labelX = xx + (labelAnchor === "end" ? -8 : 8);
    const label = marker.label
      ? `<text x="${labelX}" y="${labelY}" fill="${marker.color}" font-size="12" font-weight="700" text-anchor="${labelAnchor}">${escapeXml(marker.label)}</text>`
      : "";
    return `${shape}${label}`;
  }).join("");
  const railEvents = events.slice(0, 4);
  const railGap = 8;
  const railWidth = railEvents.length
    ? (width - 32 - railGap * (railEvents.length - 1)) / railEvents.length
    : 0;
  const eventRailSvg = railEvents.map((event, index) => {
    const xx = outerX + 16 + index * (railWidth + railGap);
    const yy = outerY + 48;
    const label = `${event.label} · ${formatTaipeiShort(event.at)} · ${formatOverlayPrice(event.price)}`;
    return `<rect x="${xx}" y="${yy}" width="${railWidth}" height="20" rx="4" fill="#10212a" stroke="${COLORS.border}"/><circle cx="${xx + 10}" cy="${yy + 10}" r="3" fill="${event.color}"/><text x="${xx + 18}" y="${yy + 14}" fill="${COLORS.text}" font-size="11">${escapeXml(label)}</text>`;
  }).join("");
  const legendRows = [
    ...displayedLevels.map((level) => ({ color: level.color, text: `${level.label} ${formatOverlayPrice(level.price)}` })),
    { color: COLORS.ema20, text: "EMA20" },
    { color: COLORS.ema50, text: "EMA50" },
    ...(showStructure ? [{ color: COLORS.resistance, text: "Structural resistance" }, { color: COLORS.support, text: "Structural support" }] : []),
  ];
  const legendSvg = legendRows.slice(0, 12).map((item, index) => {
    const column = index % 4;
    const row = Math.floor(index / 4);
    const xx = outerX + 16 + column * 375;
    const yy = outerY + height - 52 + row * 16;
    const pillWidth = Math.min(330, 30 + item.text.length * 7);
    return `<rect x="${xx}" y="${yy - 14}" width="${pillWidth}" height="19" rx="4" fill="#10212a" stroke="${COLORS.border}"/><rect x="${xx + 8}" y="${yy - 7}" width="8" height="3" fill="${item.color}"/><text x="${xx + 22}" y="${yy}" fill="${COLORS.text}" font-size="11">${escapeXml(item.text)}</text>`;
  }).join("");
  return `<g>
    <rect x="${outerX}" y="${outerY}" width="${width}" height="${height}" rx="8" fill="${COLORS.panel}" stroke="${COLORS.border}"/>
    <text x="${outerX + 16}" y="${outerY + 22}" fill="${COLORS.text}" font-size="16" font-weight="700">${escapeXml(title)}</text>
    <text x="${outerX + 16}" y="${outerY + 39}" fill="${COLORS.dim}" font-size="11">${escapeXml(subtitle)}</text>
    ${eventRailSvg}
    <clipPath id="${clipId}"><rect x="${left}" y="${top}" width="${plotWidth}" height="${plotHeight}"/></clipPath>
    ${horizontalGrid}${verticalGrid}
    <g clip-path="url(#${clipId})">${zoneSvg}${levelSvg}${structureSvg}${candleSvg}${emaSvg}${markerSvg}</g>
    ${legendSvg}
  </g>`;
}

function snapshotAssetFile(tradeId: string): string | null {
  return /^[a-z0-9-]{4,64}$/i.test(tradeId) ? `${tradeId}.svg` : null;
}

function unavailableSnapshot(requestedAt: string, entryAt: string | null, exitAt: string | null, reason: string): DailyRangeClosedChartSnapshot {
  return {
    version: DAILY_RANGE_CLOSED_CHART_SNAPSHOT_VERSION,
    status: "UNAVAILABLE",
    requestedAt,
    capturedAt: null,
    source: "BINANCE_USDM_COMPLETED_CANDLES",
    entryAt,
    exitAt,
    assetFile: null,
    mimeType: null,
    fiveMinuteCandleCount: 0,
    fourHourCandleCount: 0,
    reason,
  };
}

export function pendingDailyRangeClosedChartSnapshot(trade: Pick<DailyRangeClosedChartSnapshotTrade, "entryFilledAt" | "entrySubmittedAt" | "exitTimestamp">, requestedAt: string): DailyRangeClosedChartSnapshot {
  return {
    version: DAILY_RANGE_CLOSED_CHART_SNAPSHOT_VERSION,
    status: "PENDING",
    requestedAt,
    capturedAt: null,
    source: "BINANCE_USDM_COMPLETED_CANDLES",
    entryAt: trade.entryFilledAt ?? trade.entrySubmittedAt ?? null,
    exitAt: trade.exitTimestamp ?? null,
    assetFile: null,
    mimeType: null,
    fiveMinuteCandleCount: 0,
    fourHourCandleCount: 0,
    reason: null,
  };
}

export function renderDailyRangeClosedChartSvg(input: {
  trade: DailyRangeClosedChartSnapshotTrade;
  fiveMinuteCandles: SnapshotCandle[];
  /** Preserved in the input shape for old callers; the snapshot deliberately renders 5m only. */
  fourHourCandles: SnapshotCandle[];
  entryAtMs: number;
  exitAtMs: number;
}): string {
  const { trade, fiveMinuteCandles, entryAtMs, exitAtMs } = input;
  const routeLabel = trade.entryPolicy === "FADE" ? "FADE" : trade.entryPolicy === "CONTINUATION" ? "CONTINUATION" : "LEGACY CONTINUATION";
  const directionText = trade.breakoutDirection ? ` · breakout ${trade.breakoutDirection}` : "";
  const signalStart = Math.min(
    entryAtMs,
    trade.confirmationBar1.openTime,
    trade.confirmationBar2.openTime,
  );
  const fiveMinuteStart = Math.min(
    signalStart - FIVE_MINUTE_EMA_CONTEXT_BARS * FIVE_MINUTE_MS,
    fiveMinuteCandles[0]?.openTime ?? signalStart,
  );
  const isDownBreakout = trade.breakoutDirection === "DOWN" || (!trade.breakoutDirection && trade.direction === "SHORT");
  const breakoutReference = isDownBreakout
    ? { label: "4H breakdown", price: trade.rangeLow, color: COLORS.rangeLow }
    : { label: "4H breakout", price: trade.rangeHigh, color: COLORS.rangeHigh };
  const acceptanceLevel: PriceLevel = {
    label: "C2 acceptance",
    price: trade.confirmationBar2.close,
    color: COLORS.acceptance,
    dash: "3 4",
  };
  // The snapshot is intentionally a 5m execution review. The Daily Range
  // reference remains as one breakout level; the opposite 4H boundary must
  // never flatten the candles or dominate the chart scale.
  const executionLevels: PriceLevel[] = [
    breakoutReference,
    acceptanceLevel,
    { label: "Entry", price: trade.entryFillPrice!, color: COLORS.entry },
    ...(positive(trade.stopPrice) ? [{ label: "Stop", price: trade.stopPrice, color: COLORS.stop }] : []),
    ...(positive(trade.takeProfitPrice) ? [{ label: "Target", price: trade.takeProfitPrice, color: COLORS.takeProfit }] : []),
    { label: "Exit", price: trade.exitPrice!, color: COLORS.exit },
  ];
  const breakoutPosition = trade.breakoutDirection === "DOWN" ? "below" : "above" as const;
  const c2Position = trade.breakoutDirection === "DOWN" ? "above" : "below" as const;
  const markers: SnapshotMarker[] = [
    {
      label: "",
      at: trade.confirmationBar1.openTime + FIVE_MINUTE_MS,
      price: trade.confirmationBar1.close,
      color: breakoutReference.color,
      position: breakoutPosition,
      labelAnchor: "end",
      labelPosition: "above",
    },
    {
      label: "",
      at: trade.confirmationBar2.openTime + FIVE_MINUTE_MS,
      price: trade.confirmationBar2.close,
      color: COLORS.acceptance,
      position: c2Position,
      labelAnchor: "start",
      labelPosition: "above",
    },
    { label: "", at: entryAtMs, price: trade.entryFillPrice!, color: COLORS.entry, position: "middle", labelAnchor: "end", labelPosition: "below" },
    { label: "", at: exitAtMs, price: trade.exitPrice!, color: COLORS.exit, position: "middle", labelAnchor: "start", labelPosition: "above" },
  ];
  const exitIsStop = positive(trade.stopPrice) && Math.abs(trade.exitPrice! - trade.stopPrice) <= Math.max(1e-10, Math.abs(trade.exitPrice!) * 1e-10);
  const events: SnapshotEvent[] = [
    { label: "C1 breakout", at: trade.confirmationBar1.openTime + FIVE_MINUTE_MS, price: trade.confirmationBar1.close, color: breakoutReference.color },
    { label: "C2 acceptance", at: trade.confirmationBar2.openTime + FIVE_MINUTE_MS, price: trade.confirmationBar2.close, color: COLORS.acceptance },
    { label: `Entry ${trade.direction}`, at: entryAtMs, price: trade.entryFillPrice!, color: COLORS.entry },
    { label: exitIsStop ? "Exit / stop" : "Exit", at: exitAtMs, price: trade.exitPrice!, color: COLORS.exit },
  ];
  const zones: RiskZone[] = [
    ...(positive(trade.stopPrice) ? [{ from: trade.entryFillPrice!, to: trade.stopPrice, color: COLORS.stop, label: "risk to SL" }] : []),
    ...(positive(trade.takeProfitPrice) ? [{ from: trade.entryFillPrice!, to: trade.takeProfitPrice, color: COLORS.takeProfit, label: "target to TP" }] : []),
  ];
  const execution = renderPanel({
    x: 32, y: 74, width: 1536, height: 754,
    title: "5m · actual execution path",
    subtitle: `${trade.symbol} · ${trade.direction} · ${routeLabel}${directionText} · ${referenceSummary(trade)}`,
    candles: fiveMinuteCandles,
    allCandles: fiveMinuteCandles,
    intervalMs: FIVE_MINUTE_MS,
    viewportStart: fiveMinuteStart,
    viewportEnd: exitAtMs + CLOSE_LABEL_RIGHT_PADDING_BARS * FIVE_MINUTE_MS,
    levels: executionLevels,
    markers,
    events,
    zones,
  });
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="860" viewBox="0 0 1600 860" role="img" aria-labelledby="snapshot-title snapshot-desc">
  <title id="snapshot-title">${escapeXml(`${trade.symbol} Daily Range 5m execution snapshot`)}</title>
  <desc id="snapshot-desc">Readable 5m execution view from completed Binance USD-M candles at or before the confirmed exit. The persisted 4H breakout boundary and the completed 5m C2 acceptance are shown as levels; C1, C2, entry, and exit are listed in a separate event rail.</desc>
  <rect width="1600" height="860" fill="${COLORS.background}"/>
  <text x="32" y="32" fill="${COLORS.text}" font-family="ui-monospace, SFMono-Regular, Menlo, monospace" font-size="20" font-weight="700">DAILY RANGE 4H · 5M TRADE SNAPSHOT</text>
  <text x="32" y="54" fill="${COLORS.dim}" font-family="ui-monospace, SFMono-Regular, Menlo, monospace" font-size="12">Completed candles through confirmed exit · 4H is the strategy reference, not a second chart</text>
  <g font-family="ui-monospace, SFMono-Regular, Menlo, monospace">${execution}</g>
</svg>`;
}

export async function captureDailyRangeClosedChartSnapshot(input: {
  directory: string;
  client: DailyRangeClosedChartSnapshotClient;
  trade: DailyRangeClosedChartSnapshotTrade;
  nowMs?: () => number;
}): Promise<DailyRangeClosedChartSnapshot> {
  const requestedAt = new Date(input.nowMs?.() ?? Date.now()).toISOString();
  const entryAtMs = toMs(input.trade.entryFilledAt ?? input.trade.entrySubmittedAt);
  const exitAtMs = toMs(input.trade.exitTimestamp);
  if (entryAtMs === null || exitAtMs === null || exitAtMs < entryAtMs || !positive(input.trade.entryFillPrice) || !positive(input.trade.exitPrice)) {
    return unavailableSnapshot(requestedAt, input.trade.entryFilledAt ?? input.trade.entrySubmittedAt ?? null, input.trade.exitTimestamp, "ordered confirmed entry and exit fills are required");
  }
  const confirmationBar1 = asSnapshotCandle(input.trade.confirmationBar1);
  const confirmationBar2 = asSnapshotCandle(input.trade.confirmationBar2);
  if (!confirmationBar1 || !confirmationBar2) {
    return unavailableSnapshot(requestedAt, input.trade.entryFilledAt ?? input.trade.entrySubmittedAt ?? null, input.trade.exitTimestamp, "persisted C1/C2 execution bars are required for a truthful close-time image");
  }
  const assetFile = snapshotAssetFile(input.trade.tradeId);
  if (!assetFile) return unavailableSnapshot(requestedAt, input.trade.entryFilledAt ?? input.trade.entrySubmittedAt ?? null, input.trade.exitTimestamp, "invalid trade id for snapshot asset");
  const signalStart = Math.min(confirmationBar1.openTime, confirmationBar2.openTime, entryAtMs);
  const fiveMinuteStart = Math.max(0, signalStart - FIVE_MINUTE_EMA_CONTEXT_BARS * FIVE_MINUTE_MS);
  const fiveMinuteEnd = Math.floor((exitAtMs - 1) / FIVE_MINUTE_MS) * FIVE_MINUTE_MS;
  try {
    const fiveMinuteRows = await input.client.getKlines(input.trade.symbol, "5m", { startTime: fiveMinuteStart, endTime: fiveMinuteEnd });
    const fiveMinuteCandles = distinctCandles(
      [...fiveMinuteRows, confirmationBar1, confirmationBar2],
      fiveMinuteStart,
      exitAtMs,
    );
    if (fiveMinuteCandles.length === 0) {
      return unavailableSnapshot(requestedAt, input.trade.entryFilledAt ?? input.trade.entrySubmittedAt ?? null, input.trade.exitTimestamp, "no completed 5m USD-M candle is available before the exit fill");
    }
    const svg = renderDailyRangeClosedChartSvg({ trade: input.trade, fiveMinuteCandles, fourHourCandles: [], entryAtMs, exitAtMs });
    const root = resolve(input.directory);
    mkdirSync(root, { recursive: true });
    const file = resolve(root, assetFile);
    if (!file.startsWith(root + sep)) {
      return unavailableSnapshot(requestedAt, input.trade.entryFilledAt ?? input.trade.entrySubmittedAt ?? null, input.trade.exitTimestamp, "snapshot path escaped its archive directory");
    }
    const temporary = `${file}.tmp-${process.pid}-${Date.now()}`;
    writeFileSync(temporary, svg, "utf8");
    renameSync(temporary, file);
    return {
      version: DAILY_RANGE_CLOSED_CHART_SNAPSHOT_VERSION,
      status: "CAPTURED",
      requestedAt,
      capturedAt: new Date(input.nowMs?.() ?? Date.now()).toISOString(),
      source: "BINANCE_USDM_COMPLETED_CANDLES",
      entryAt: input.trade.entryFilledAt ?? input.trade.entrySubmittedAt,
      exitAt: input.trade.exitTimestamp,
      assetFile,
      mimeType: "image/svg+xml",
      fiveMinuteCandleCount: fiveMinuteCandles.length,
      fourHourCandleCount: 0,
      reason: null,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      ...pendingDailyRangeClosedChartSnapshot(input.trade, requestedAt),
      reason: `snapshot source unavailable: ${message}`,
    };
  }
}

/** Read only a filename persisted by this module; no user-derived file path is accepted. */
export function readDailyRangeClosedChartSnapshotSvg(
  directory: string,
  snapshot: DailyRangeClosedChartSnapshot | null | undefined,
): string | null {
  if (snapshot?.status !== "CAPTURED" || snapshot.mimeType !== "image/svg+xml" || !snapshot.assetFile) return null;
  const root = resolve(directory);
  if (!/^[a-z0-9-]{4,64}\.svg$/i.test(snapshot.assetFile)) return null;
  const file = resolve(root, snapshot.assetFile);
  if (!file.startsWith(root + sep)) return null;
  try {
    return readFileSync(file, "utf8");
  } catch {
    return null;
  }
}
